content.verifier:tests/meta/config.json:
{
  "allow_create": false,
  "rigorous_codebase": true,
  "data_deps_include": [
    "smollm2-360m",
    "smollm2-1.7b",
    "smollm2-fineweb-edu",
    "lm-eval-datasets",
    "lm-eval-mmlu-obqa"
  ],
  "test_cmds": [
    {
      "cmd": "scripts/smollm2_360m_kv12.sh",
      "label": "smollm2-360m-kv12",
      "group": 1,
      "compute": 1.0,
      "time": "4:00:00",
      "package": "nanoGPT"
    },
    {
      "cmd": "scripts/smollm2_360m_kv31.sh",
      "label": "smollm2-360m-kv31",
      "group": 1,
      "compute": 1.0,
      "time": "4:00:00",
      "package": "nanoGPT"
    },
    {
      "cmd": "scripts/smollm2_1p7b_kv12.sh",
      "label": "smollm2-1.7b-kv12",
      "group": 1,
      "compute": 1.0,
      "time": "8:00:00",
      "package": "nanoGPT"
    }
  ],
  "baselines": {
    "naive_svd": {
      "edit_ops": "edits/naive_svd.edit.py"
    },
    "mha2mla": {
      "edit_ops": "edits/mha2mla.edit.py"
    },
    "transmla": {
      "edit_ops": "edits/transmla.edit.py"
    },
    "care": {
      "edit_ops": "edits/care.edit.py"
    }
  },
  "files": [
    {
      "filename": "nanoGPT/mla_convert.py",
      "read": [
        {
          "start": -1,
          "end": -1
        }
      ],
      "edit": [
        {
          "start": 37,
          "end": 140
        }
      ]
    },
    {
      "filename": "nanoGPT/mla_lib.py",
      "read": [
        {
          "start": -1,
          "end": -1
        }
      ]
    }
  ],
  "seeds": [
    42
  ],
  "harbor_bake_data_deps": [
    "smollm2-360m",
    "smollm2-1.7b",
    "smollm2-fineweb-edu",
    "lm-eval-datasets",
    "lm-eval-mmlu-obqa"
  ],
  "harbor_resources": {
    "storage_mb": 102400,
    "memory_mb": 131072,
    "cpus": 24,
    "build_timeout_sec": 7200
  },
  "harbor_trusted_result": true,
  "_harbor_trusted_result_note": "stage 1 (the submission's convert(), python mla_convert.py) runs via $MLSBENCH_RUN_UNTRUSTED under a fresh uid with its stage-1 directory as the only writable path, after the zero-shot datasets were made root-only; stage 2 (scripts/mla_recover.py + edits/mla_lib.py from the root-only task meta copy, digest-checked before and after stage 1) runs via $MLSBENCH_TRUSTED_PYTHON, reads the verifier-only scored text from $MLSBENCH_TASK_DIR/data/ and the shell appends the single FINAL_TEST_METRICS line + MLSBENCH_TERMINAL_OK to $MLSBENCH_RESULT_FILE, the only thing the verifier parses",
  "harbor_strip_paths": [
    "/data/smollm2-fineweb-edu/val.bin",
    "/data/smollm2-fineweb-edu/wikitext2.bin"
  ],
  "_harbor_strip_paths_note": "the scored LM text (the first 256 windows of val.bin, the WikiText-2 test stream) is verifier-only (holdout/llm-gqa-to-mla-conversion/data -> tests/meta/data, sha256-pinned in scripts/mla_recover.py); the baked smollm2-fineweb-edu dep keeps only train.bin (calibration + recovery fine-tune)",
  "data_deps": [
    {
      "name": "lm-eval-mmlu-obqa",
      "description": "OpenBookQA (allenai/openbookqa main) + MMLU (cais/mmlu, 57 subjects) as an offline HF-datasets cache for lm-eval's openbookqa and mmlu_continuation (the cloze MMLU of the small-model MLA-conversion papers); prepared inside the task image so the cache layout matches datasets 2.21.0 (~17 MB)",
      "host_path": "{data_root}/lm-eval-mmlu-obqa",
      "container_path": "/data/lm-eval-mmlu-obqa",
      "ready_files": [
        "{data_root}/lm-eval-mmlu-obqa/.complete"
      ],
      "prepare": "vendor/data_scripts/nanoGPT/prepare_mmlu_obqa.py"
    }
  ]
}
